+{"version":3,"sources":["/workspace/repo/plugins/catalog-backend/src/service/createRouter.ts"],"sourcesContent":["/*\n * Copyright 2020 The Backstage Authors\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *     http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport {\n  ANNOTATION_LOCATION,\n  ANNOTATION_ORIGIN_LOCATION,\n  Entity,\n  parseLocationRef,\n  stringifyEntityRef,\n} from '@backstage/catalog-model';\nimport { Config } from '@backstage/config';\nimport { InputError, serializeError } from '@backstage/errors';\nimport express from 'express';\nimport yn from 'yn';\nimport { z } from 'zod';\nimport { Cursor, EntitiesCatalog } from '../catalog/types';\nimport { CatalogProcessingOrchestrator } from '../processing/types';\nimport { validateEntityEnvelope } from '../processing/util';\nimport {\n  basicEntityFilter,\n  entitiesBatchRequest,\n  parseEntityFilterParams,\n  parseEntityTransformParams,\n  parseQueryEntitiesParams,\n} from './request';\nimport { parseEntityFacetParams } from './request/parseEntityFacetParams';\nimport { parseEntityOrderParams } from './request/parseEntityOrderParams';\nimport { LocationService, RefreshService } from './types';\nimport {\n  disallowReadonlyMode,\n  encodeCursor,\n  locationInput,\n  validateRequestBody,\n} from './util';\nimport { createOpenApiRouter } from '../schema/openapi';\nimport { parseEntityPaginationParams } from './request/parseEntityPaginationParams';\nimport {\n  AuditorService,\n  AuthService,\n  HttpAuthService,\n  LoggerService,\n  SchedulerService,\n  PermissionsService,\n} from '@backstage/backend-plugin-api';\nimport { LocationAnalyzer } from '@backstage/plugin-catalog-node';\nimport { AuthorizedValidationService } from './AuthorizedValidationService';\nimport {\n  createEntityArrayJsonStream,\n  writeEntitiesResponse,\n  writeSingleEntityResponse,\n} from './response';\n\n/**\n * Options used by {@link createRouter}.\n *\n * @public\n * @deprecated Please migrate to the new backend system as this will be removed in the future.\n */\nexport interface RouterOptions {\n  entitiesCatalog?: EntitiesCatalog;\n  locationAnalyzer?: LocationAnalyzer;\n  locationService: LocationService;\n  orchestrator?: CatalogProcessingOrchestrator;\n  refreshService?: RefreshService;\n  scheduler?: SchedulerService;\n  logger: LoggerService;\n  config: Config;\n  permissionIntegrationRouter?: express.Router;\n  auth: AuthService;\n  httpAuth: HttpAuthService;\n  permissionsService: PermissionsService;\n  auditor?: AuditorService;\n  disableRelationsCompatibility?: boolean;\n}\n\n/**\n * Creates a catalog router.\n */\nexport async function createRouter(\n  options: RouterOptions,\n): Promise<express.Router> {\n  const router = await createOpenApiRouter({\n    validatorOptions: {\n      // We want the spec to be up to date with the expected value, but the return type needs\n      //  to be controlled by the router implementation not the request validator.\n      ignorePaths: /^\\/validate-entity\\/?$/,\n    },\n  });\n  const {\n    entitiesCatalog,\n    locationAnalyzer,\n    locationService,\n    orchestrator,\n    refreshService,\n    config,\n    logger,\n    permissionIntegrationRouter,\n    permissionsService,\n    auth,\n    httpAuth,\n    disableRelationsCompatibility = false,\n  } = options;\n\n  const readonlyEnabled =\n    config.getOptionalBoolean('catalog.readonly') || false;\n  if (readonlyEnabled) {\n    logger.info('Catalog is running in readonly mode');\n  }\n\n  if (refreshService) {\n    router.post('/refresh', async (req, res) => {\n      const { authorizationToken, ...restBody } = req.body;\n\n      const credentials = authorizationToken\n        ? await auth.authenticate(authorizationToken)\n        : await httpAuth.credentials(req);\n\n      await refreshService.refresh({\n        ...restBody,\n        credentials,\n      });\n      res.status(200).end();\n    });\n  }\n\n  if (permissionIntegrationRouter) {\n    router.use(permissionIntegrationRouter);\n  }\n\n  if (entitiesCatalog) {\n    router\n      .get('/entities', async (req, res) => {\n        const filter = parseEntityFilterParams(req.query);\n        const fields = parseEntityTransformParams(req.query);\n        const order = parseEntityOrderParams(req.query);\n        const pagination = parseEntityPaginationParams(req.query);\n        const credentials = await httpAuth.credentials(req);\n\n        // When pagination parameters are passed in, use the legacy slow path\n        // that loads all entities into memory\n\n        if (pagination || disableRelationsCompatibility !== true) {\n          const { entities, pageInfo } = await entitiesCatalog.entities({\n            filter,\n            fields,\n            order,\n            pagination,\n            credentials,\n          });\n\n          // Add a Link header to the next page\n          if (pageInfo.hasNextPage) {\n            const url = new URL(`http://ignored${req.url}`);\n            url.searchParams.delete('offset');\n            url.searchParams.set('after', pageInfo.endCursor);\n            res.setHeader('link', `<${url.pathname}${url.search}>; rel=\"next\"`);\n          }\n\n          await writeEntitiesResponse({\n            res,\n            items: entities,\n            alwaysUseObjectMode: !disableRelationsCompatibility,\n          });\n          return;\n        }\n\n        const responseStream = createEntityArrayJsonStream(res);\n        const limit = 10000;\n        let cursor: Cursor | undefined;\n\n        try {\n          let currentWrite: Promise<boolean> | undefined = undefined;\n          do {\n            const result = await entitiesCatalog.queryEntities(\n              !cursor\n                ? {\n                    credentials,\n                    fields,\n                    limit,\n                    filter,\n                    orderFields: order,\n                    skipTotalItems: true,\n                  }\n                : { credentials, fields, limit, cursor },\n            );\n\n            // Wait for previous write to complete\n            if (await currentWrite) {\n              return; // Client closed connection\n            }\n\n            if (result.items.entities.length) {\n              currentWrite = responseStream.send(result.items);\n            }\n\n            cursor = result.pageInfo?.nextCursor;\n          } while (cursor);\n\n          // Wait for last write to complete\n          await currentWrite;\n\n          responseStream.complete();\n        } finally {\n          responseStream.close();\n        }\n      })\n      .get('/entities/by-query', async (req, res) => {\n        const { items, pageInfo, totalItems } =\n          await entitiesCatalog.queryEntities({\n            limit: req.query.limit,\n            offset: req.query.offset,\n            ...parseQueryEntitiesParams(req.query),\n            credentials: await httpAuth.credentials(req),\n          });\n\n        await writeEntitiesResponse({\n          res,\n          items,\n          alwaysUseObjectMode: !disableRelationsCompatibility,\n          responseWrapper: entities => ({\n            items: entities,\n            totalItems,\n            pageInfo: {\n              ...(pageInfo.nextCursor && {\n                nextCursor: encodeCursor(pageInfo.nextCursor),\n              }),\n              ...(pageInfo.prevCursor && {\n                prevCursor: encodeCursor(pageInfo.prevCursor),\n              }),\n            },\n          }),\n        });\n      })\n      .get('/entities/by-uid/:uid', async (req, res) => {\n        const { uid } = req.params;\n        const { entities } = await entitiesCatalog.entities({\n          filter: basicEntityFilter({ 'metadata.uid': uid }),\n          credentials: await httpAuth.credentials(req),\n        });\n        writeSingleEntityResponse(res, entities, `No entity with uid ${uid}`);\n      })\n      .delete('/entities/by-uid/:uid', async (req, res) => {\n        const { uid } = req.params;\n        await entitiesCatalog.removeEntityByUid(uid, {\n          credentials: await httpAuth.credentials(req),\n        });\n        res.status(204).end();\n      })\n      .get('/entities/by-name/:kind/:namespace/:name', async (req, res) => {\n        const { kind, namespace, name } = req.params;\n        const { items } = await entitiesCatalog.entitiesBatch({\n          entityRefs: [stringifyEntityRef({ kind, namespace, name })],\n          credentials: await httpAuth.credentials(req),\n        });\n        writeSingleEntityResponse(\n          res,\n          items,\n          `No entity named '${name}' found, with kind '${kind}' in namespace '${namespace}'`,\n        );\n      })\n      .get(\n        '/entities/by-name/:kind/:namespace/:name/ancestry',\n        async (req, res) => {\n          const { kind, namespace, name } = req.params;\n          const entityRef = stringifyEntityRef({ kind, namespace, name });\n          const response = await entitiesCatalog.entityAncestry(entityRef, {\n            credentials: await httpAuth.credentials(req),\n          });\n          res.status(200).json(response);\n        },\n      )\n      .post('/entities/by-refs', async (req, res) => {\n        const request = entitiesBatchRequest(req);\n        const { items } = await entitiesCatalog.entitiesBatch({\n          entityRefs: request.entityRefs,\n          filter: parseEntityFilterParams(req.query),\n          fields: parseEntityTransformParams(req.query, request.fields),\n          credentials: await httpAuth.credentials(req),\n        });\n        await writeEntitiesResponse({\n          res,\n          items,\n          alwaysUseObjectMode: !disableRelationsCompatibility,\n          responseWrapper: entities => ({\n            items: entities,\n          }),\n        });\n      })\n      .get('/entity-facets', async (req, res) => {\n        const response = await entitiesCatalog.facets({\n          filter: parseEntityFilterParams(req.query),\n          facets: parseEntityFacetParams(req.query),\n          credentials: await httpAuth.credentials(req),\n        });\n        res.status(200).json(response);\n      });\n  }\n\n  if (locationService) {\n    router\n      .post('/locations', async (req, res) => {\n        const location = await validateRequestBody(req, locationInput);\n        const dryRun = yn(req.query.dryRun, { default: false });\n\n        // when in dryRun addLocation is effectively a read operation so we don't\n        // need to disallow readonly\n        if (!dryRun) {\n          disallowReadonlyMode(readonlyEnabled);\n        }\n\n        const output = await locationService.createLocation(location, dryRun, {\n          credentials: await httpAuth.credentials(req),\n        });\n        res.status(201).json(output);\n      })\n      .get('/locations', async (req, res) => {\n        const locations = await locationService.listLocations({\n          credentials: await httpAuth.credentials(req),\n        });\n        res.status(200).json(locations.map(l => ({ data: l })));\n      })\n\n      .get('/locations/:id', async (req, res) => {\n        const { id } = req.params;\n        const output = await locationService.getLocation(id, {\n          credentials: await httpAuth.credentials(req),\n        });\n        res.status(200).json(output);\n      })\n      .delete('/locations/:id', async (req, res) => {\n        disallowReadonlyMode(readonlyEnabled);\n\n        const { id } = req.params;\n        await locationService.deleteLocation(id, {\n          credentials: await httpAuth.credentials(req),\n        });\n        res.status(204).end();\n      })\n      .get('/locations/by-entity/:kind/:namespace/:name', async (req, res) => {\n        const { kind, namespace, name } = req.params;\n        const output = await locationService.getLocationByEntity(\n          { kind, namespace, name },\n          { credentials: await httpAuth.credentials(req) },\n        );\n        res.status(200).json(output);\n      });\n  }\n\n  if (locationAnalyzer) {\n    router.post('/analyze-location', async (req, res) => {\n      const body = await validateRequestBody(\n        req,\n        z.object({\n          location: locationInput,\n          catalogFilename: z.string().optional(),\n        }),\n      );\n      const schema = z.object({\n        location: locationInput,\n        catalogFilename: z.string().optional(),\n      });\n      const credentials = await httpAuth.credentials(req);\n      const parsedBody = schema.parse(body);\n      try {\n        const output = await locationAnalyzer.analyzeLocation(\n          parsedBody,\n          credentials,\n        );\n        res.status(200).json(output);\n      } catch (err) {\n        if (\n          // Catch errors from parse-url library.\n          err.name === 'Error' &&\n          'subject_url' in err\n        ) {\n          throw new InputError('The given location.target is not a URL');\n        }\n        throw err;\n      }\n    });\n  }\n\n  if (orchestrator) {\n    router.post('/validate-entity', async (req, res) => {\n      const bodySchema = z.object({\n        entity: z.unknown(),\n        location: z.string(),\n      });\n\n      let body: z.infer<typeof bodySchema>;\n      let entity: Entity;\n      let location: { type: string; target: string };\n      try {\n        body = await validateRequestBody(req, bodySchema);\n        entity = validateEntityEnvelope(body.entity);\n        location = parseLocationRef(body.location);\n        if (location.type !== 'url')\n          throw new TypeError(\n            `Invalid location ref ${body.location}, only 'url:<target>' is supported, e.g. url:https://host/path`,\n          );\n      } catch (err) {\n        return res.status(400).json({\n          errors: [serializeError(err)],\n        });\n      }\n\n      const credentials = await httpAuth.credentials(req);\n      const authorizedValidationService = new AuthorizedValidationService(\n        orchestrator,\n        permissionsService,\n      );\n      const processingResult = await authorizedValidationService.process(\n        {\n          entity: {\n            ...entity,\n            metadata: {\n              ...entity.metadata,\n              annotations: {\n                [ANNOTATION_LOCATION]: body.location,\n                [ANNOTATION_ORIGIN_LOCATION]: body.location,\n                ...entity.metadata.annotations,\n              },\n            },\n          },\n        },\n        credentials,\n      );\n\n      if (!processingResult.ok)\n        res.status(400).json({\n          errors: processingResult.errors.map(e => serializeError(e)),\n        });\n      return res.status(200).end();\n    });\n  }\n\n  return router;\n}\n"],"names":["createRouter","options","router","createOpenApiRouter","validatorOptions","ignorePaths","entitiesCatalog","locationAnalyzer","locationService","orchestrator","refreshService","config","logger","permissionIntegrationRouter","permissionsService","auth","httpAuth","disableRelationsCompatibility","readonlyEnabled","getOptionalBoolean","info","post","req","res","authorizationToken","restBody","body","credentials","authenticate","refresh","status","end","use","get","filter","parseEntityFilterParams","query","fields","parseEntityTransformParams","order","parseEntityOrderParams","pagination","parseEntityPaginationParams","entities","pageInfo","hasNextPage","url","URL","searchParams","delete","set","endCursor","setHeader","pathname","search","writeEntitiesResponse","items","alwaysUseObjectMode","responseStream","createEntityArrayJsonStream","limit","cursor","currentWrite","undefined","result","queryEntities","orderFields","skipTotalItems","length","send","nextCursor","complete","close","totalItems","offset","parseQueryEntitiesParams","responseWrapper","encodeCursor","prevCursor","uid","params","basicEntityFilter","writeSingleEntityResponse","removeEntityByUid","kind","namespace","name","entitiesBatch","entityRefs","stringifyEntityRef","entityRef","response","entityAncestry","json","request","entitiesBatchRequest","facets","parseEntityFacetParams","location","validateRequestBody","locationInput","dryRun","yn","default","disallowReadonlyMode","output","createLocation","locations","listLocations","map","l","data","id","getLocation","deleteLocation","getLocationByEntity","z","object","catalogFilename","string","optional","schema","parsedBody","parse","analyzeLocation","err","InputError","bodySchema","entity","unknown","validateEntityEnvelope","parseLocationRef","type","TypeError","errors","serializeError","authorizedValidationService","AuthorizedValidationService","processingResult","process","metadata","annotations","ANNOTATION_LOCATION","ANNOTATION_ORIGIN_LOCATION","ok","e"],"mappings":"AAAA;;;;;;;;;;;;;;CAcC;;;;+BA6EqBA;;;eAAAA;;;8BArEf;wBAEoC;2DAE5B;qBACG;sBAGqB;yBAOhC;wCACgC;wCACA;uBAOhC;yBAC6B;6CACQ;6CAUA;0BAKrC;;;;;;AA4BA,eAAeA,aACpBC,OAAsB;IAEtB,MAAMC,SAAS,MAAMC,IAAAA,4BAAmB,EAAC;QACvCC,kBAAkB;YAChB,uFAAuF;YACvF,4EAA4E;YAC5EC,aAAa;QACf;IACF;IACA,MAAM,EACJC,eAAe,EACfC,gBAAgB,EAChBC,eAAe,EACfC,YAAY,EACZC,cAAc,EACdC,MAAM,EACNC,MAAM,EACNC,2BAA2B,EAC3BC,kBAAkB,EAClBC,IAAI,EACJC,QAAQ,EACRC,gCAAgC,KAAK,EACtC,GAAGhB;IAEJ,MAAMiB,kBACJP,OAAOQ,kBAAkB,CAAC,uBAAuB;IACnD,IAAID,iBAAiB;QACnBN,OAAOQ,IAAI,CAAC;IACd;IAEA,IAAIV,gBAAgB;QAClBR,OAAOmB,IAAI,CAAC,YAAY,OAAOC,KAAKC;YAClC,MAAM,EAAEC,kBAAkB,EAAE,GAAGC,UAAU,GAAGH,IAAII,IAAI;YAEpD,MAAMC,cAAcH,qBAChB,MAAMT,KAAKa,YAAY,CAACJ,sBACxB,MAAMR,SAASW,WAAW,CAACL;YAE/B,MAAMZ,eAAemB,OAAO,CAAC;gBAC3B,GAAGJ,QAAQ;gBACXE;YACF;YACAJ