    let repo = url.pathname.split('/-/blob/')[0].split('/blob/')[0];\n\n    // Get gitlab relative path\n    const relativePath = getGitLabIntegrationRelativePath(config);\n\n    // Check relative path exist and replace it if it's the case.\n    if (relativePath) {\n      repo = repo.replace(relativePath, '');\n    }\n\n    // Convert\n    // to: https://gitlab.com/api/v4/projects/groupA%2Fteams%2FsubgroupA%2FteamA%2Frepo\n    const repoIDLookup = new URL(\n      `${url.origin}${relativePath}/api/v4/projects/${encodeURIComponent(\n        repo.replace(/^\\//, ''),\n      )}`,\n    );\n\n    const response = await fetch(\n      repoIDLookup.toString(),\n      getGitLabRequestOptions(config),\n    );\n\n    const data = await response.json();\n\n    if (!response.ok) {\n      throw new Error(\n        `GitLab Error '${data.error}', ${data.error_description}`,\n      );\n    }\n\n    return Number(data.id);\n  } catch (e) {\n    throw new Error(`Could not get GitLab project ID for: ${target}, ${e}`);\n  }\n}\n"],"names":["buildProjectUrl","getGitLabFileFetchUrl","getGitLabRequestOptions","getProjectId","url","config","projectID","toString","token","headers","startsWith","Authorization","configToken","target","URL","branchAndFilePath","pathname","split","slice","join","branch","filePath","relativePath","getGitLabIntegrationRelativePath","encodeURIComponent","decodeURIComponent","search","e","Error","includes","repo","replace","repoIDLookup","origin","response","fetch","data","json","ok","error","error_description","Number","id"],"mappings":"AAAA;;;;;;;;;;;;;;CAcC;;;;;;;;;;;;;;;;;IA8DeA,eAAe;eAAfA;;IArCMC,qBAAqB;eAArBA;;IAcNC,uBAAuB;eAAvBA;;IA0DMC,YAAY;eAAZA;;;mEA/FJ;wBAIX;;;;;;AAmBA,eAAeF,sBACpBG,GAAW,EACXC,MAA+B;IAE/B,MAAMC,YAAY,MAAMH,aAAaC,KAAKC;IAC1C,OAAOL,gBAAgBI,KAAKE,WAAWD,QAAQE,QAAQ;AACzD;AAQO,SAASL,wBACdG,MAA+B,EAC/BG,KAAc;IAEd,IAAIA,OAAO;QACT,uJAAuJ;QACvJ,OAAO;YACLC,SAASD,MAAME,UAAU,CAAC,QACtB;gBAAE,iBAAiBF;YAAM,IACzB;gBAAEG,eAAe,CAAC,OAAO,EAAEH,OAAO;YAAC;QACzC